import csv

# Load both files and compare
sensor = {}
with open('sensor_data.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        t = float(row['time'])
        sensor[t] = {
            'lead_speed': float(row['lead_speed']) if row['lead_speed'] else None,
            'distance': float(row['distance']) if row['distance'] else None,
        }

results = {}
with open('simulation_results.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        t = float(row['time'])
        results[t] = {
            'ego_speed': float(row['ego_speed']),
            'distance': float(row['distance']) if row['distance'] else None,
            'distance_error': float(row['distance_error']) if row['distance_error'] else None,
        }

print("t, lead_speed, ego_speed, sim_dist, dist_err")
for t in [30, 35, 40, 45, 50, 55, 60, 65, 70, 75]:
    if t in sensor and t in results:
        lead = sensor[t]['lead_speed']
        ego = results[t]['ego_speed']
        dist = results[t]['distance']
        err = results[t]['distance_error']
        print(f"{t}, {lead:.1f}, {ego:.1f}, {dist:.1f}, {err:.1f}")
